SELECT T1.name, CAST(COUNT(T2.person_id) AS REAL) * 100 / (SELECT COUNT(*) FROM Credit) AS pct
FROM Person T1 JOIN Credit T2 ON T1.person_id = T2.person_id
GROUP BY T1.person_id ORDER BY COUNT(T2.person_id) DESC LIMIT 1;

SELECT p.first, p.last, CAST(strftime('%Y', o.DATE) AS INTEGER) - CAST(strftime('%Y', p.birthdate) AS INTEGER) AS age
FROM observations o JOIN patients p ON p.patient=o.PATIENT
WHERE o.DATE LIKE '2011%' AND o.DESCRIPTION='Systolic Blood Pressure' AND o.VALUE=200 AND o.UNITS='mmHg' AND p.deathdate IS NULL;

SELECT CAST(SUM(month) AS REAL) / COUNT(*) AS avg_duration
FROM longest_absense_from_school
WHERE name NOT IN (SELECT name FROM male);
